#!/usr/bin/env node
/**
 * Generates the component API reference module consumed by the docs app:
 *   projects/docs/src/app/generated/component-api.generated.ts
 *
 * Input is docs/quality/inventory.json (regenerated by tools/quality/inventory.mjs).
 * The output is committed so the docs build needs no prebuild step; drift is
 * caught in CI via --check (part of verify:docs).
 *
 * Usage:
 *   node tools/docs/generate-component-api.mjs          # regenerate
 *   node tools/docs/generate-component-api.mjs --check  # fail on drift
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import prettier from "prettier";
import { buildComponentApi, renderComponentApiModule } from "./component-api-lib.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const inventoryPath = path.join(root, "docs/quality/inventory.json");
const outputPath = path.join(
  root,
  "projects/docs/src/app/generated/component-api.generated.ts",
);

const check = process.argv.includes("--check");

const inventory = JSON.parse(fs.readFileSync(inventoryPath, "utf8"));
const api = buildComponentApi(inventory);
const source = renderComponentApiModule(api);

const config = {
  ...(await prettier.resolveConfig(outputPath, { editorconfig: true })),
  filepath: outputPath,
};
const formatted = await prettier.format(source, config);

const entryCount = Object.values(api).reduce(
  (total, members) =>
    total + members.reduce((sum, member) => sum + member.entries.length, 0),
  0,
);

if (check) {
  const current = fs.existsSync(outputPath)
    ? fs.readFileSync(outputPath, "utf8")
    : null;
  if (current !== formatted) {
    console.error(
      `${path.relative(root, outputPath)} is stale. Run: npm run docs:generate-api`,
    );
    process.exit(1);
  }
  console.log(
    `component API reference up to date (${Object.keys(api).length} families, ${entryCount} entries).`,
  );
  process.exit(0);
}

fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, formatted);
console.log(
  `wrote ${path.relative(root, outputPath)} (${Object.keys(api).length} families, ${entryCount} entries).`,
);
